Output12Time Complexity: O(n * log(K)), Each insertion and removal operation in a heap takes O(log(K)), and we perform this operation n times for the array.Auxiliary Space: O(K), The heap stores at most K elements at a time.[QuickSelect] Works Best in Practice - O(n) on average time and O(n) spaceThis is an optimization over method 1, if QuickSort is used as a sorting algorithm in first step. In QuickSort, pick a pivot element, then move the pivot element to its correct position and partition the surrounding array. The idea is, not to do complete quicksort, but stop at the point where pivot itself is k'th largest element. Also, not to recur for both left and right sides of pivot, but recur for one of them according to the position of pivot. Step-by-step approach:Pick a random pivot from the array.Partitioning the array into three parts:leftArr: Elements greater than the pivot.midArr: Elements equal to the pivot.rightArr: Elements less than the pivot.Check if k is smaller than or equal to size of leftArr then search into leftArr.If k is greater than size of leftArr + size of midArr then adjust k and search into rightArr.Otherwise, return the pivot (it’s the k-th largest element)Below is the implementation of the above approach:
            C++

    #include <bits/stdc++.h>
using namespace std;

// Function to perform quick select
int quickSelect(vector<int> &arr, int k){

    // Randomly select a pivot index from the array
    int pivotIdx = rand() % arr.size();

    // Get the pivot value
    int pivot = arr[pivotIdx]; 


    // For keeping elements greater than the pivot
    vector<int> leftArr; 

    // For keeping elements equal to the pivot
    vector<int> midArr; 

    // For keeping elements less than the pivot
    vector<int> rightArr; 

    // Partitioning the array based on the pivot
    for (int val : arr){
        if (val > pivot){
            leftArr.push_back(val); 
        }
        else if (val < pivot){
            rightArr.push_back(val); 
        }
        else{
            midArr.push_back(val); 
        }
    }

    // Recursive selection based on the size of the partitions
    if (k <= leftArr.size()){

        // If k is in the left partition, recurse into it
        return quickSelect(leftArr, k);
    }
    if (leftArr.size() + midArr.size() < k){

        // If k is in the right partition, adjust k and recurse
        return quickSelect(rightArr, k - leftArr.size() 
                                             - midArr.size());
    }

    // If k is in the mid partition, return the pivot
    return pivot;
}

// Wrapper function to find the k-th largest element
int KthLargest(vector<int> &arr, int k){

     // Call quickSelect to find k-th largest
    return quickSelect(arr, k);
}

int main(){
    vector<int> arr = {12, 3, 5, 7, 19};
    int k = 2; 
    cout << KthLargest(arr, k);

    return 0; 
}


