Output12Time Complexity: O(n) on average, O(n2) in the worst caseAuxiliary Space: O(n)[Other Approach] Using Counting Sort (Not efficient for large range of elements)Lets suppose the range of the numbers is small and limited between -10^5 and 10^5, then we can take the advantage to use counting sort, we can count the occurrences of each number in this range and then determine the k-th largest element by traversing the counts in reverse order (since we are interested in the largest elements).
            C++

    #include <bits/stdc++.h>
using namespace std;

// Function to find the K-th largest element using counting sort
int kthLargest(vector<int>& arr, int K) {

    // The range for -10^5 to 10^5
    int range = 200010;
    vector<int> freq(range, 0);

    // Count the frequency of each number
    for (int val : arr) {
        freq[val + 100000]++;
    }

    // Traverse the frequency array from the largest to smallest
    int count = 0;
    for (int i = range - 1; i >= 0; i--) {
        count += freq[i];

        // Once we reach the K-th largest, return the number
        if (count >= K) {

            // Convert back to the original value
            return i - 100000; 
        }
    }

    // In case K doesn't exist
    return -1; 
}

int main() {
    vector<int> arr = {12, 3, 5, 7, 19};
    int K = 2;

    cout << kthLargest(arr, K) << endl;
    return 0;
}


